#!ibl edition=2
$s0 = [limbs:browser]{op:"snapshot"}
$before = $s0.snapshot >> [table:filter]{where:($e)=>$e.role=="link" or $e.role=="button"}
$mb = ($s0.snapshot >> [table:filter]{where:($e)=>$e.role=="button" and contains($e.name,"보기")})[0]
$h = [limbs:browser]{op:"hover", ref:$mb.ref}
$s1 = [limbs:browser]{op:"snapshot"}
$after = $s1.snapshot >> [table:filter]{where:($e)=>$e.role=="link" or $e.role=="button"}
$late = $s1.snapshot >> [table:filter]{where:($e)=>$e.role=="link" and $e.name=="지연만"}
$ck = len($late)>0 ? "found" : "missing"
return {before:$before, hover:$h, after:$after, late:$late, ck:$ck}
